// Corpus-sourced fast-event observer evaluation in actual PRSE GameCore 3D physics.
// 100 human + 100 systematically sampled assisted SceneEval proposals (frozen).
// A physical event is generated by one bounded GameCore impulse on the first
// suitable dynamic object. Only ray-verified eyewitnesses receive its event;
// an occluded observer's knowledge is restricted to later changed facts.
// Source descriptions/individual cases are stored privately, not committed.
import {writeFileSync,readFileSync, mkdirSync} from 'node:fs';
import {performance} from 'node:perf_hooks';
import {createHash}from'node:crypto';
import {initializePhysics}from'../../physics-core.js';
import {PRSELoop,geometryIssues}from'../2026-10-24/prse_semantic_roundtrip.mjs';
import {readResearchEvidence}from'../2026-10-24/prse_research_evidence_io.mjs';
import {repairScene}from'./prse_relation_local_optimizer.mjs';
import {PRSEPhysicalObserver}from'./prse_physical_observer.mjs';

await initializePhysics();
const path='/data/var/games/prse_semantic_research/runs/2026-10-25-physical-visibility/';
const eventSynchronous=process.argv.includes('--event-synchronous');
const version=process.argv.find(x=>x.startsWith('--output-tag='))?.slice(13)
 ||(eventSynchronous?'v2':'v1');
if(!/^[a-z][a-z0-9-]{0,30}$/.test(version))throw Error('Invalid replay tag');
mkdirSync(path,{recursive:true,mode:0o700});
const source=JSON.parse(readResearchEvidence('prse_semantic_constraints_eval_all500_v3.json')).proposalsAll500;
const scenes=[
 ...source.slice(0,100).map(p=>({p,sourceType:'human'})),
 ...source.filter((p,i)=>i>=100&&(i-100)%4===0).slice(0,100).map(p=>({p,sourceType:'assisted'}))
];
const viewpoints=[
 {x:-27,y:1.5,z:11.8},
 {x:-32.8,y:1.5,z:7.9},
 {x:-21,y:1.5,z:7.9},
 {x:-32.8,y:1.5,z:15.7},
 {x:-21,y:1.5,z:15.7}
];
const validEye=(world,eye)=>{
 let hit=false;
 world.game.world.intersectionsWithPoint(eye,()=>{hit=true;return false;});
 return !hit;
};
const raw=[];
const started=performance.now();
for(const {p,sourceType}of scenes){
 const rec={id:p.sourceId,sourceType,status:'not_eligible',validScenes:0,
  dynamicBodies:0,visibleCandidates:0,occludedCandidates:0,
  queuedVisible:0,queuedOccluded:0,deliveredVisible:0,deliveredOccluded:0,
  afterRestoreRepeated:0,sourceTextStillOriginal:false};
 const proposal=repairScene(p,{maxSweeps:2,maxAttemptsPerScene:150});
 if(!proposal.accepted||geometryIssues(proposal.scene).length){
  rec.status='physically_rejected';raw.push(rec);continue;
 }
 const dynamic=proposal.scene.entities.filter(e=>e.body==='dynamic');
 rec.dynamicBodies=dynamic.length;
 if(!dynamic.length){rec.status='no_dynamic_object';raw.push(rec);continue;}
 let game=null,copy=null;
 try{
  game=new PRSELoop(proposal.scene);game.tick(18);rec.validScenes=1;
  const trial=new PRSEPhysicalObserver(game,{visibilityRadius:9});
  let chosen=null;
  for(const entity of dynamic){
   const eyes=viewpoints.filter(eye=>validEye(game,eye));
   const seen=[],hidden=[];
   for(const eye of eyes){
    const short=trial.isVisible(entity.id,eye,{radius:9,mode:'distance'});
    if(!short.visible)continue;
    const ray=trial.isVisible(entity.id,eye,{radius:9,mode:'ray'});
    if(ray.visible)seen.push(eye);
    else if(ray.reason==='occluded_by_physical_collision')hidden.push(eye);
   }
   rec.visibleCandidates+=seen.length;rec.occludedCandidates+=hidden.length;
   if(seen.length&&(!chosen||hidden.length)){
    chosen={entity,eye:seen[0],hidden: hidden[0]||null};
    if(hidden.length)break;
   }
  }
  if(!chosen){rec.status='no_valid_viewpoint';raw.push(rec);continue;}
  rec.status='eligible_dynamic';
  rec.chosenCategory=chosen.entity.kind;
  rec.hasOccludedContrast=!!chosen.hidden;
  trial.observe('witness',chosen.eye,{radius:9});
  if(chosen.hidden)trial.observe('unseen',chosen.hidden,{radius:9});
  if(eventSynchronous){
   trial.attach('witness',()=>chosen.eye,{radius:9});
   if(chosen.hidden)trial.attach('unseen',()=>chosen.hidden,{radius:9});
  }
  if(!game.applyImpulse(chosen.entity.id,{x:.8,y:.3,z:1.4}))throw Error('GameCore impulse denied');
  const eventSequence=game.events.findLast(x=>x.type==='external_impulse')?.sequence;
  if(eventSynchronous){
   const records=trial.snapshot().observers;
   rec.queuedVisible=records.find(o=>o.id==='witness').queuedEvents.includes(eventSequence)?1:0;
   rec.queuedOccluded=chosen.hidden?(records.find(o=>o.id==='unseen').queuedEvents.includes(eventSequence)?1:0):0;
  }
  game.tick(1);
  if(!eventSynchronous){
   const v=trial.captureFrame('witness',chosen.eye,{radius:9});
   const h=chosen.hidden?trial.captureFrame('unseen',chosen.hidden,{radius:9}):null;
   rec.queuedVisible=v.queuedWitnessEvents;
   rec.queuedOccluded=h?.queuedWitnessEvents??0;
  }
  if(game.eventSubscriberErrors.length)throw Error('One or more physical witness callbacks failed');
  game.tick(60);
  const world=PRSELoop.restore(JSON.parse(JSON.stringify(game.snapshot())));
  if(!world.ok)throw Error('Scene save rejected');
  copy=world.loop;
  const persisted=PRSEPhysicalObserver.restore(copy,
    JSON.parse(JSON.stringify(trial.snapshot())));
  const displayed=persisted.observe('witness',chosen.eye,{radius:9});
  rec.deliveredVisible=displayed.witnessedEvents.filter(x=>x.capturedAtEventTime&&x.sequence===eventSequence).length;
  rec.afterRestoreRepeated=persisted.observe('witness',chosen.eye,{radius:9}).witnessedEvents.length;
  rec.deliveredOccluded=chosen.hidden?
   persisted.observe('unseen',chosen.hidden,{radius:9}).witnessedEvents.filter(x=>x.sequence===eventSequence).length:0;
  rec.sourceTextStillOriginal=copy.scene.prose===p.text;
  rec.status='evaluated';
 }catch(e){rec.status='runtime_failure';rec.error=String(e.message).slice(0,130);}
 finally{copy?.dispose();game?.dispose();}
 raw.push(rec);
}
const aggregate={sourceScenes:200,
 validScenes:raw.filter(x=>x.validScenes).length,
 withDynamicBodies:raw.filter(x=>x.dynamicBodies>0).length,
 evaluated:raw.filter(x=>x.status==='evaluated').length,
 withOccludedContrast:raw.filter(x=>x.status==='evaluated'&&x.hasOccludedContrast).length,
 actualPhysicsWitnessQueued:raw.filter(x=>x.status==='evaluated'&&x.queuedVisible>=1).length,
 delayedPhysicsWitnessDelivered:raw.filter(x=>x.status==='evaluated'&&x.deliveredVisible>=1).length,
 occludedCauseWronglyQueued:raw.filter(x=>x.status==='evaluated'&&x.queuedOccluded!==0).length,
 occludedCauseWronglyDelivered:raw.filter(x=>x.status==='evaluated'&&x.deliveredOccluded!==0).length,
 repeatedAfterSave:raw.filter(x=>x.status==='evaluated'&&x.afterRestoreRepeated>0).length,
 stableSourceProse:raw.filter(x=>x.status==='evaluated'&&x.sourceTextStillOriginal).length,
 runtimeFailures:raw.filter(x=>x.status==='runtime_failure').length,
 skippedNoValidViewpoint:raw.filter(x=>x.status==='no_valid_viewpoint').length,
 totalWallMs:+(performance.now()-started).toFixed(1)};
const full={metadata:{
 study:'Existing PRSE GameCore/Rapier real bodies, frozen text-only external SceneEval proposals',
 noGoldLabels:true,noModelCalls:true,captureMode:eventSynchronous?'emission-synchronous':'post-step',
 impulse:'Fixed x=0.8,y=0.3,z=1.4 mass-dependent GameCore impulse; no human play',
 observer:'Five fixed candidate camera points, only physically non-overlapping and visibility-confirmed',
 limits:'Selected eligible dynamic bodies only; extrapolation to all story events and human perception not justified'},
 aggregate,rows:raw};
const filename=path+'prse_observer_event_batch_200_raw_'+version+'.json';
writeFileSync(filename,JSON.stringify(full,null,2)+'\n',{flag:'wx',mode:0o600});
writeFileSync(new URL('prse_observer_event_batch_200_aggregate_'+version+'.json',import.meta.url),
 JSON.stringify({metadata:{...full.metadata,rawSHA256:createHash('sha256').update(readFileSync(filename)).digest('hex'),
  privateSource:filename},aggregate,
 bySubset:Object.fromEntries(['human','assisted'].map(k=>{
  const subset=raw.filter(r=>r.sourceType===k);
  return [k,{scenes:subset.length,withDynamic:subset.filter(r=>r.dynamicBodies>0).length,
   evaluated:subset.filter(r=>r.status==='evaluated').length,
   occludedContrast:subset.filter(r=>r.status==='evaluated'&&r.hasOccludedContrast).length,
   delivered:subset.filter(r=>r.deliveredVisible>0).length}];
 }))},null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify(aggregate));
